package io.github.diodeme.ji.session.sqlite;

import io.github.diodeme.ji.session.tck.SessionRepositoryTck;
import io.github.diodeme.ji.session.tree.SessionRepository;
import java.io.IOException;
import java.nio.file.Files;

final class SqliteSessionRepositoryTckTest extends SessionRepositoryTck {
    @Override
    protected SessionRepository createRepository() {
        try {
            return new SqliteSessionRepository(Files.createTempFile("ji-sqlite-tck-", ".db"));
        } catch (IOException exception) {
            throw new IllegalStateException(exception);
        }
    }
}
